package imgproxy_test

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// jsCoreEntry is one URL generated by @imgproxy/imgproxy-js-core
// (testdata/jscore/generate.ts).
type jsCoreEntry struct {
	Name    string         `json:"name"`
	Source  string         `json:"source"`
	Type    string         `json:"type"`
	Options map[string]any `json:"options"`
	Path    string         `json:"path"`
}

func loadJSCore(tb testing.TB) []jsCoreEntry {
	tb.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", "jscore", "corpus.json"))
	if err != nil {
		tb.Fatal(err)
	}
	var corpus []jsCoreEntry
	if err := json.Unmarshal(b, &corpus); err != nil {
		tb.Fatal(err)
	}
	return corpus
}

// TestJSCoreCorpus parses URLs built by the official imgproxy URL generator
// from option objects; the expected requests are in golden/jscore.json.
func TestJSCoreCorpus(t *testing.T) {
	t.Parallel()
	corpus := loadJSCore(t)
	if len(corpus) < 30 {
		t.Fatalf("corpus has %d entries, want >= 30", len(corpus))
	}
	cases := make([]testCase, 0, len(corpus))
	for _, e := range corpus {
		cases = append(cases, testCase{name: e.Name, path: "/unsafe" + e.Path})
	}
	runGolden(t, "jscore", cases)

	// Every generated URL must round-trip its source exactly.
	p := getFixture(t).parsers["default"]
	for _, e := range corpus {
		res, err := p.ParsePath("/unsafe" + e.Path)
		if err != nil {
			t.Errorf("%s: %v", e.Name, err)
			continue
		}
		if res.SourceString != e.Source {
			t.Errorf("%s: source %q, want %q", e.Name, res.SourceString, e.Source)
		}
	}
}
